-- Ejecutar únicamente en una base de práctica vacía (o esquema vacío), con codificación Unicode.
-- Importes de esta semilla: enteros en MXN. Fechas ISO, booleanos representados por 0/1.
-- No incluye borrado ni credenciales. La creación de tablas puede confirmar cambios según el motor.

CREATE TABLE "CATEGORIAS" (
  "ID" NUMBER(19,0) NOT NULL,
  "NOMBRE" NVARCHAR2(255) NOT NULL,
  "DESCRIPCION" NVARCHAR2(255) DEFAULT NULL,
  PRIMARY KEY ("ID"),
  UNIQUE ("NOMBRE")
);
CREATE TABLE "PROVEEDORES" (
  "ID" NUMBER(19,0) NOT NULL,
  "NOMBRE" NVARCHAR2(255) NOT NULL,
  "PAIS" NVARCHAR2(255) NOT NULL,
  "EMAIL" NVARCHAR2(255),
  PRIMARY KEY ("ID")
);
CREATE TABLE "PRODUCTOS" (
  "ID" NUMBER(19,0) NOT NULL,
  "NOMBRE" NVARCHAR2(255) NOT NULL,
  "CATEGORIA" NVARCHAR2(255) NOT NULL,
  "PRECIO" NUMBER(19,0) NOT NULL,
  "STOCK" NUMBER(19,0) DEFAULT 0 NOT NULL,
  "PROVEEDOR_ID" NUMBER(19,0),
  "ACTIVO" NUMBER(19,0) DEFAULT 1 NOT NULL,
  PRIMARY KEY ("ID"),
  FOREIGN KEY ("CATEGORIA") REFERENCES "CATEGORIAS" ("NOMBRE"),
  FOREIGN KEY ("PROVEEDOR_ID") REFERENCES "PROVEEDORES" ("ID") ON DELETE SET NULL,
  CHECK ("PRECIO" >= 0),
  CHECK ("STOCK" >= 0),
  CHECK ("ACTIVO" IN (0, 1))
);
CREATE TABLE "CLIENTES" (
  "ID" NUMBER(19,0) NOT NULL,
  "NOMBRE" NVARCHAR2(255) NOT NULL,
  "EMAIL" NVARCHAR2(255) NOT NULL,
  "CIUDAD" NVARCHAR2(255) NOT NULL,
  "FECHA_ALTA" DATE NOT NULL,
  "TELEFONO" NVARCHAR2(255),
  PRIMARY KEY ("ID"),
  UNIQUE ("EMAIL")
);
CREATE TABLE "DEPARTAMENTOS" (
  "ID" NUMBER(19,0) NOT NULL,
  "NOMBRE" NVARCHAR2(255) NOT NULL,
  PRIMARY KEY ("ID"),
  UNIQUE ("NOMBRE")
);
CREATE TABLE "EMPLEADOS" (
  "ID" NUMBER(19,0) NOT NULL,
  "NOMBRE" NVARCHAR2(255) NOT NULL,
  "DEPARTAMENTO_ID" NUMBER(19,0) NOT NULL,
  "GERENTE_ID" NUMBER(19,0),
  "SALARIO" NUMBER(19,0) NOT NULL,
  "FECHA_INGRESO" DATE NOT NULL,
  PRIMARY KEY ("ID"),
  FOREIGN KEY ("DEPARTAMENTO_ID") REFERENCES "DEPARTAMENTOS" ("ID"),
  FOREIGN KEY ("GERENTE_ID") REFERENCES "EMPLEADOS" ("ID"),
  CHECK ("SALARIO" > 0)
);
CREATE TABLE "PEDIDOS" (
  "ID" NUMBER(19,0) NOT NULL,
  "CLIENTE_ID" NUMBER(19,0) NOT NULL,
  "EMPLEADO_ID" NUMBER(19,0),
  "FECHA" DATE NOT NULL,
  "ESTADO" NVARCHAR2(255) DEFAULT N'pendiente' NOT NULL,
  PRIMARY KEY ("ID"),
  FOREIGN KEY ("CLIENTE_ID") REFERENCES "CLIENTES" ("ID"),
  FOREIGN KEY ("EMPLEADO_ID") REFERENCES "EMPLEADOS" ("ID") ON DELETE SET NULL,
  CHECK ("ESTADO" IN (N'pendiente', N'entregado', N'cancelado'))
);
CREATE TABLE "DETALLE_PEDIDOS" (
  "PEDIDO_ID" NUMBER(19,0) NOT NULL,
  "PRODUCTO_ID" NUMBER(19,0) NOT NULL,
  "CANTIDAD" NUMBER(19,0) DEFAULT 1 NOT NULL,
  "PRECIO_UNITARIO" NUMBER(19,0) NOT NULL,
  "DESCUENTO" NUMBER(19,0) DEFAULT 0 NOT NULL,
  PRIMARY KEY ("PEDIDO_ID", "PRODUCTO_ID"),
  FOREIGN KEY ("PEDIDO_ID") REFERENCES "PEDIDOS" ("ID") ON DELETE CASCADE,
  FOREIGN KEY ("PRODUCTO_ID") REFERENCES "PRODUCTOS" ("ID"),
  CHECK ("CANTIDAD" > 0),
  CHECK ("PRECIO_UNITARIO" >= 0),
  CHECK ("DESCUENTO" >= 0),
  CHECK ("DESCUENTO" <= 100)
);
CREATE TABLE "PAGOS" (
  "ID" NUMBER(19,0) NOT NULL,
  "PEDIDO_ID" NUMBER(19,0) NOT NULL,
  "FECHA" DATE NOT NULL,
  "IMPORTE" NUMBER(19,0) NOT NULL,
  "METODO" NVARCHAR2(255) NOT NULL,
  PRIMARY KEY ("ID"),
  FOREIGN KEY ("PEDIDO_ID") REFERENCES "PEDIDOS" ("ID") ON DELETE CASCADE,
  CHECK ("IMPORTE" > 0),
  CHECK ("METODO" IN (N'tarjeta', N'transferencia', N'efectivo'))
);
CREATE TABLE "ALMACENES" (
  "ID" NUMBER(19,0) NOT NULL,
  "NOMBRE" NVARCHAR2(255) NOT NULL,
  "CIUDAD" NVARCHAR2(255) NOT NULL,
  PRIMARY KEY ("ID")
);
CREATE TABLE "INVENTARIO" (
  "ALMACEN_ID" NUMBER(19,0) NOT NULL,
  "PRODUCTO_ID" NUMBER(19,0) NOT NULL,
  "UNIDADES" NUMBER(19,0) DEFAULT 0 NOT NULL,
  PRIMARY KEY ("ALMACEN_ID", "PRODUCTO_ID"),
  FOREIGN KEY ("ALMACEN_ID") REFERENCES "ALMACENES" ("ID"),
  FOREIGN KEY ("PRODUCTO_ID") REFERENCES "PRODUCTOS" ("ID") ON DELETE CASCADE,
  CHECK ("UNIDADES" >= 0)
);
CREATE TABLE "MOVIMIENTOS_STOCK" (
  "ID" NUMBER(19,0) NOT NULL,
  "PRODUCTO_ID" NUMBER(19,0) NOT NULL,
  "ALMACEN_ID" NUMBER(19,0) NOT NULL,
  "EMPLEADO_ID" NUMBER(19,0),
  "FECHA" DATE NOT NULL,
  "TIPO" NVARCHAR2(255) NOT NULL,
  "CANTIDAD" NUMBER(19,0) NOT NULL,
  PRIMARY KEY ("ID"),
  FOREIGN KEY ("PRODUCTO_ID") REFERENCES "PRODUCTOS" ("ID"),
  FOREIGN KEY ("ALMACEN_ID") REFERENCES "ALMACENES" ("ID"),
  FOREIGN KEY ("EMPLEADO_ID") REFERENCES "EMPLEADOS" ("ID") ON DELETE SET NULL,
  CHECK ("CANTIDAD" > 0),
  CHECK ("TIPO" IN (N'entrada', N'salida'))
);
CREATE TABLE "CUENTAS" (
  "ID" NUMBER(19,0) NOT NULL,
  "CLIENTE_ID" NUMBER(19,0) NOT NULL,
  "SALDO" NUMBER(19,0) DEFAULT 0 NOT NULL,
  "FECHA_APERTURA" DATE NOT NULL,
  PRIMARY KEY ("ID"),
  UNIQUE ("CLIENTE_ID"),
  FOREIGN KEY ("CLIENTE_ID") REFERENCES "CLIENTES" ("ID") ON DELETE CASCADE,
  CHECK ("SALDO" >= 0)
);

COMMIT;
